import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import '../../../core/theme/tokens.dart';
import '../../../core/utils/media_upload.dart';
import '../../../core/widgets/common.dart';
import '../../../core/widgets/ui_kit.dart';
import '../../downloads/domain/download_record.dart';
import '../../shell/app_shell.dart';
import '../../viewer/external_files.dart';
import '../../viewer/offline_pdf.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_file_item.dart';
import 'studio_tools_screen.dart';
import 'studio_export_sheet.dart';
import 'studio_annotation_screen.dart';
import 'scan_pdf_screen.dart';
import 'rich_document_screen.dart';
import '../data/studio_pdf_engine.dart';

enum _StudioFilter { all, edited, mergedSplit, docs, external }

String _studioMime(String path) => switch (path.split('.').last.toLowerCase()) {
  'pdf' => 'application/pdf',
  'doc' => 'application/msword',
  'docx' =>
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'ppt' => 'application/vnd.ms-powerpoint',
  'pptx' =>
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'xls' => 'application/vnd.ms-excel',
  'xlsx' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'txt' => 'text/plain',
  'md' => 'text/markdown',
  'jpg' || 'jpeg' => 'image/jpeg',
  'png' => 'image/png',
  'webp' => 'image/webp',
  _ => 'application/octet-stream',
};

class PdfStudioScreen extends ConsumerStatefulWidget {
  const PdfStudioScreen({super.key});

  @override
  ConsumerState<PdfStudioScreen> createState() => _PdfStudioScreenState();
}

class _PdfStudioScreenState extends ConsumerState<PdfStudioScreen> {
  _StudioFilter _filter = _StudioFilter.all;
  String _query = '';
  bool _opening = false;

  Future<void> _open() async {
    if (_opening) return;
    setState(() => _opening = true);
    try {
      final picked = await StudioPdfEngine.pickFiles();
      StudioFileItem? last;
      for (final file in picked) {
        last = await ref.read(pdfStudioHistoryProvider.notifier).importFile(file.path,
          originalFileName: file.name, sourceType: 'DEVICE', operationBadge: 'IMPORTED');
      }
      if (mounted && last != null) context.push('/pdf-studio/viewer/${last.id}');
    } catch (_) { if (mounted) showHSnack(context, 'Could not open this file. Please retry.', error: true); }
    finally { if (mounted) setState(() => _opening = false); }
  }
  Future<void> _blank() async {
    try {
      final path = await StudioPdfEngine.compose([StudioPage.blank()]);
      final file = await ref.read(pdfStudioHistoryProvider.notifier).importFile(path,
        originalFileName: 'Untitled.pdf', sourceType: 'CREATED', operationBadge: 'CREATED');
      if (mounted) context.push('/pdf-studio/viewer/${file.id}');
    } catch (_) { if (mounted) showHSnack(context, 'Could not create a PDF.', error: true); }
  }
  void _tool(StudioTool tool) => Navigator.of(context, rootNavigator: true).push(MaterialPageRoute<void>(
    builder: (_) => tool == StudioTool.document ? const RichDocumentScreen() : StudioToolsScreen(tool: tool)));
  Future<void> _template() async {
    final template = await showModalBottomSheet<String>(context: context, showDragHandle: true,
      builder: (c) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [
        for (final title in ['Study notes', 'Revision checklist']) ListTile(leading: const Icon(Icons.description_outlined), title: Text(title), onTap: () => Navigator.pop(c, title)),
      ])));
    if (mounted && template != null) Navigator.of(context, rootNavigator: true).push(MaterialPageRoute<void>(builder: (_) => RichDocumentScreen(template: template)));
  }

  bool _matches(StudioFileItem file) {
    final filterMatch = switch (_filter) {
      _StudioFilter.all => true,
      _StudioFilter.edited => file.operationBadge == 'EDITED',
      _StudioFilter.mergedSplit =>
        file.operationBadge == 'MERGED' || file.operationBadge == 'SPLIT',
      _StudioFilter.docs => file.fileCategory == 'DOC',
      _StudioFilter.external => file.sourceType == 'EXTERNAL_INTENT',
    };
    return filterMatch &&
        (_query.isEmpty ||
            '${file.displayName} ${file.originalFileName}'
                .toLowerCase()
                .contains(_query.toLowerCase()));
  }

  @override
  Widget build(BuildContext context) {
    final history = ref
        .watch(pdfStudioHistoryProvider)
        .where(_matches)
        .toList();
    final external = ref.watch(externalHistoryProvider);
    final knownPaths = ref
        .watch(pdfStudioHistoryProvider)
        .map((item) => item.internalFilePath)
        .toSet();
    final notImported =
        _filter == _StudioFilter.all || _filter == _StudioFilter.external
        ? external.where((item) => !knownPaths.contains(item.path)).toList()
        : const <ExternalDocument>[];
    final theme = Theme.of(context);

    return TabPage(
      title: 'PDF Studio',
      subtitle: 'Read · Edit · Study · Succeed',
      slivers: [
        SliverPadding(
          padding: const EdgeInsets.symmetric(horizontal: HSpace.screen),
          sliver: SliverList.list(
            children: [
              Container(padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: theme.colorScheme.outlineVariant),
                  gradient: LinearGradient(colors: [theme.colorScheme.surface, theme.colorScheme.primary.withValues(alpha: .09)])),
                child: Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Icon(Icons.picture_as_pdf_rounded, size: 30, color: theme.colorScheme.primary), const Gap(10),
                  Text('Your PDF Workspace', style: theme.textTheme.titleMedium), const Gap(5),
                  Text('Read, annotate and organize\nall your study materials.', style: theme.textTheme.bodySmall),
                ])), Transform.rotate(angle: .15, child: Container(width: 68, height: 98,
                  decoration: BoxDecoration(color: theme.colorScheme.primary.withValues(alpha: .1), borderRadius: BorderRadius.circular(12)),
                  child: Icon(Icons.subject_rounded, size: 48, color: theme.colorScheme.primary.withValues(alpha: .6)))),
                ])),
              const Gap(12),
              Row(children: [
                Expanded(child: OutlinedButton.icon(onPressed: _opening ? null : _open, icon: const Icon(Icons.folder_open_rounded, size: 21), label: const Text('Open File'))),
                const Gap(10),
                Expanded(child: FilledButton.tonalIcon(onPressed: () => showCreatePdf(context), icon: const Icon(Icons.add_box_outlined, size: 21), label: const Text('Create PDF'))),
              ]),
              if (_opening) const LinearProgressIndicator(minHeight: 2),
              const Gap(18),
              const SectionHeader(title: 'Create New'), const Gap(10),
              LayoutBuilder(builder: (c, box) => Wrap(spacing: 10, runSpacing: 10, children: [
                for (final a in <(String, IconData, VoidCallback)>[
                  ('Blank PDF', Icons.description_rounded, _blank),
                  ('From Images', Icons.photo_library_outlined, () => context.push('/create-pdf?source=gallery')),
                  ('Scan Document', Icons.camera_alt_outlined, () => context.push('/create-pdf?source=camera')),
                  ('From Template', Icons.description_outlined, _template),
                ]) SizedBox(width: (box.maxWidth - 30) / 4, child: _StudioAction(label: a.$1, icon: a.$2, onTap: a.$3)),
              ])),
              const Gap(20),
              Row(children: [Expanded(child: Text('Recent Files', style: theme.textTheme.titleLarge)),
                PopupMenuButton<StudioTool>(tooltip: 'PDF tools', onSelected: _tool,
                  itemBuilder: (_) => const [
                    PopupMenuItem(value: StudioTool.merge, child: Text('Merge PDFs')),
                    PopupMenuItem(value: StudioTool.split, child: Text('Split PDF')),
                    PopupMenuItem(value: StudioTool.organize, child: Text('Organize pages')),
                    PopupMenuItem(value: StudioTool.document, child: Text('Write document')),
                  ], child: Padding(padding: const EdgeInsets.all(10), child: Text('Tools', style: theme.textTheme.labelLarge?.copyWith(color: theme.colorScheme.primary)))),
              ]),
              HSearchField(
                hint: 'Search recent files',
                onChanged: (value) => setState(() => _query = value),
              ),
              const Gap(HSpace.sm),
              SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    for (final filter in _StudioFilter.values)
                      Padding(
                        padding: const EdgeInsets.only(right: 5),
                        child: ChoiceChip(
                          label: Text(switch (filter) {
                            _StudioFilter.all => 'All recent',
                            _StudioFilter.edited => 'Edited',
                            _StudioFilter.mergedSplit => 'Merged & split',
                            _StudioFilter.docs => 'Docs',
                            _StudioFilter.external => 'External (saved)',
                          }),
                          selected: _filter == filter,
                          visualDensity: VisualDensity.compact,
                          materialTapTargetSize:
                              MaterialTapTargetSize.shrinkWrap,
                          onSelected: (_) => setState(() => _filter = filter),
                        ),
                      ),
                  ],
                ),
              ),
              const Gap(HSpace.sm),
              if (history.isEmpty && notImported.isEmpty)
                const EmptyState(
                  icon: Icons.description_outlined,
                  title: 'Your workspace is ready',
                  message: 'Open a document to start.',
                ),
              for (final file in history) _StudioHistoryTile(file: file),
              if (notImported.isNotEmpty) ...[
                const Gap(HSpace.md),
                Text(
                  'Opened with PHARM D WITH HYZEN',
                  style: theme.textTheme.titleMedium,
                ),
                Text('Recent device files', style: theme.textTheme.bodySmall),
                const Gap(HSpace.xs),
                for (final file in notImported)
                  ResourceTile(
                    icon: Icons.file_present_rounded,
                    color: HColors.primary,
                    eyebrow: 'DEVICE IMPORT',
                    title: file.title,
                    subtitle:
                        'Opened ${file.openedAt.toLocal().toString().split('.').first}',
                    trailing: IconButton(
                      tooltip: 'Save to PDF Studio workspace',
                      icon: const Icon(Icons.save_alt_rounded),
                      onPressed: () async {
