Future<void> showCreatePdf(BuildContext context) async {
  final router = GoRouter.of(context);
  final source = await showModalBottomSheet<String>(context: context, showDragHandle: true,
    builder: (c) => SafeArea(child: Padding(padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
      child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text('Create PDF', style: Theme.of(c).textTheme.titleLarge), const SizedBox(height: 12),
        ListTile(leading: const Icon(Icons.camera_alt_rounded), title: const Text('Scan with camera'),
          subtitle: const Text('Capture and add pages'), onTap: () => Navigator.pop(c, 'camera')),
        ListTile(leading: const Icon(Icons.photo_library_outlined), title: const Text('From gallery images'),
          subtitle: const Text('Select photos, arrange and save'), onTap: () => Navigator.pop(c, 'gallery')),
      ]))));
