class ScanPdfScreen extends ConsumerStatefulWidget {
  const ScanPdfScreen({super.key, this.initialAction});
  final String? initialAction;
  @override
  ConsumerState<ScanPdfScreen> createState() => _ScanPdfScreenState();
}

class _ScanPdfScreenState extends ConsumerState<ScanPdfScreen> with WidgetsBindingObserver {
  static const _camera = MethodChannel('com.hyzen.pharmd/camera_pages');
  final _name = TextEditingController(text: 'Scanned notes');
  List<String> _pages = [];
  bool _busy = true;
  String? _error;
  bool get _android => !kIsWeb && defaultTargetPlatform == TargetPlatform.android;
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) => _restore());
  }
  Future<void> _restore() async {
    try {
      if (_android) _pages = await _camera.invokeListMethod<String>('recover') ?? [];
    } catch (_) { /* The draft is optional on unsupported platforms. */ }
    if (!mounted) return;
    setState(() => _busy = false);
    if (widget.initialAction == 'camera') { await _capture(); }
    else if (widget.initialAction == 'gallery') { await _gallery(); }
  }
  @override
  void dispose() { WidgetsBinding.instance.removeObserver(this); _name.dispose(); super.dispose(); }
  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && !_busy && _android) _refreshDraft();
  }
  Future<void> _refreshDraft() async {
    try { final pages = await _camera.invokeListMethod<String>('recover');
      if (mounted && !_busy && pages != null) setState(() => _pages = pages);
    } catch (_) {}
  }
  Future<void> _work(Future<void> Function() action) async {
    if (_busy) return;
    setState(() { _busy = true; _error = null; });
    try { await action(); }
    on PlatformException catch (e) { if (mounted) setState(() => _error = e.message ?? 'Could not prepare this page. Please retry.'); }
    catch (_) { if (mounted) setState(() => _error = 'Could not finish. Your pages are still here; please retry.'); }
    finally { if (mounted) setState(() => _busy = false); }
  }
  Future<void> _capture() => _work(() async {
    final paths = await _camera.invokeListMethod<String>('capture');
    if (mounted && paths != null) setState(() => _pages = paths);
  });
  Future<void> _gallery() => _work(() async {
    final files = await StudioPdfEngine.pickFiles();
    final paths = files.where((f) => RegExp(r'\.(jpe?g|png|webp)$', caseSensitive: false).hasMatch(f.path)).map((f) => f.path).toList();
    if (files.isNotEmpty && paths.isEmpty) throw PlatformException(code: 'images', message: 'Choose JPG, PNG or WebP images.');
    if (paths.isEmpty) return;
    final next = _android ? await _camera.invokeListMethod<String>('addImages', {'paths': paths}) : [..._pages, ...paths];
    if (mounted && next != null) setState(() => _pages = next);
  });
  Future<void> _replace(List<String> pages) => _work(() async {
    final next = _android ? await _camera.invokeListMethod<String>('replace', {'paths': pages}) : pages;
    if (mounted && next != null) setState(() => _pages = next);
  });
  Future<void> _rotate(String path) => _work(() async {
    final next = await _camera.invokeListMethod<String>('rotate', {'path': path});
    if (mounted && next != null) setState(() => _pages = next);
  });
  Future<void> _save() => _work(() async {
    if (_pages.isEmpty) return;
    final path = await StudioPdfEngine.imagesToPdf(_pages);
    final count = await StudioPdfEngine.pageCount(path);
    if (count != _pages.length) throw const FormatException('Incomplete PDF');
    final name = _name.text.trim().replaceFirst(RegExp(r'\.pdf$', caseSensitive: false), '');
    final item = await ref.read(pdfStudioHistoryProvider.notifier).importFile(path,
      originalFileName: '${name.isEmpty ? 'Scanned notes' : name}.pdf', sourceType: 'IMAGE_SCAN', operationBadge: 'SCANNED');
    await ref.read(pdfStudioHistoryProvider.notifier).updatePageCount(item.id, count);
    if (_android) await _camera.invokeMethod<bool>('clear');
    if (mounted) { showHSnack(context, 'PDF saved to your workspace'); context.replace('/pdf-studio/viewer/${item.id}'); }
  });
  @override
  Widget build(BuildContext context) {
    final t = Theme.of(context);
    return PopScope(canPop: !_busy, child: Scaffold(
      appBar: HTopBar(title: 'Create PDF', subtitle: '${_pages.length} pages',
        onBack: () { if (!_busy) { if (context.canPop()) { context.pop(); } else { context.go('/pdf-studio'); } } }),
      body: Column(children: [
        if (_busy) const LinearProgressIndicator(minHeight: 2),
        if (_error != null) Padding(padding: const EdgeInsets.all(12), child: Text(_error!, style: TextStyle(color: t.colorScheme.error))),
        Padding(padding: const EdgeInsets.fromLTRB(16, 10, 16, 8), child: TextField(controller: _name, maxLength: 100,
          decoration: const InputDecoration(labelText: 'PDF name', isDense: true, counterText: ''))),
        Expanded(child: _pages.isEmpty
          ? const EmptyState(icon: Icons.document_scanner_outlined, title: 'Add your first page', message: 'Capture a page or choose photos below.')
          : ReorderableListView.builder(padding: const EdgeInsets.all(16), itemCount: _pages.length,
            onReorder: (oldIndex, newIndex) { if (_busy) return; final next = [..._pages]; if (newIndex > oldIndex) newIndex--; next.insert(newIndex, next.removeAt(oldIndex)); _replace(next); },
            itemBuilder: (c, i) => Card(key: ValueKey(_pages[i]), margin: const EdgeInsets.only(bottom: 10),
              child: Padding(padding: const EdgeInsets.all(8), child: Row(children: [
                SizedBox(width: 70, height: 90, child: ScanPageImage(path: _pages[i])), const SizedBox(width: 12),
                Expanded(child: Text('Page ${i + 1}', style: t.textTheme.titleSmall)),
                if (_android) IconButton(tooltip: 'Rotate page ${i + 1}', onPressed: _busy ? null : () => _rotate(_pages[i]), icon: const Icon(Icons.rotate_right_rounded, size: 20)),
                IconButton(tooltip: 'Remove page ${i + 1}', onPressed: _busy ? null : () => _replace([..._pages]..removeAt(i)), icon: const Icon(Icons.close_rounded, size: 20)),
                if (!_busy) const Icon(Icons.drag_handle_rounded, size: 20), const SizedBox(width: 10),
              ]))))),
      ]),
      bottomNavigationBar: SafeArea(top: false, child: Padding(padding: const EdgeInsets.fromLTRB(12, 8, 12, 10),
        child: Row(children: [
          if (_android) Expanded(child: OutlinedButton.icon(onPressed: _busy ? null : _capture, icon: const Icon(Icons.add_a_photo_outlined, size: 19), label: const Text('Capture'))),
          const SizedBox(width: 8),
          IconButton(tooltip: 'Choose gallery images', onPressed: _busy ? null : _gallery, icon: const Icon(Icons.photo_library_outlined)),
          const SizedBox(width: 8),
          Expanded(child: FilledButton.icon(onPressed: _busy || _pages.isEmpty ? null : _save,
            icon: const Icon(Icons.picture_as_pdf_rounded, size: 19), label: const Text('Save PDF'))),
        ])),
      ),
    ));
  }
}

class ScanPageImage extends StatefulWidget {
  const ScanPageImage({super.key, required this.path});
  final String path;
  @override
  State<ScanPageImage> createState() => _ScanPageImageState();
}
class _ScanPageImageState extends State<ScanPageImage> {
  late final Future<Uint8List> _bytes = documentBytes(widget.path);
  @override
  Widget build(BuildContext context) => FutureBuilder<Uint8List>(future: _bytes,
    builder: (_, s) => s.hasData ? Image.memory(s.data!, cacheWidth: 180, fit: BoxFit.contain,
      errorBuilder: (_, __, ___) => const Icon(Icons.image_outlined)) : const Icon(Icons.image_outlined));
}

