              color: Theme.of(context).brightness == Brightness.light
                  ? Color.alphaBlend(color.withValues(alpha: .08), Colors.white)
                  : null,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  IconBadge(
                    icon: Icons.science_rounded,
                    color: color,
                    size: 36,
